pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address caller1, address caller2) public {
        // Admissible: both callers are not the zero address; the property compares returns from two different callers without ownership transfer.
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        vm.assume(caller1 != caller2);

        // read owner from caller1
        vm.prank(caller1);
        address ownerFromCaller1 = c.owner();

        // read owner from caller2
        vm.prank(caller2);
        address ownerFromCaller2 = c.owner();

        // The owner getter must return the same immutable owner for all callers.
        assertTrue(ownerFromCaller1 == ownerFromCaller2);
    }
}

