pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }
    function testFuzz_property(bool ignore) public {
        // The property: owner() should never revert in the reference contract.
        // The buggy version inserts revert() into owner(), causing it to always revert.
        bool ok;
        try c.owner() returns (address o) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "owner() should not revert");
    }
}

