// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address newOwner, address caller) public {
        // Ensure the current owner is address(this) from setUp.
        address originalOwner = c.owner();
        require(originalOwner == address(this), "owner must be this contract");

        // Make sure the caller is NOT the current owner (this contract) so the bug can be triggered.
        vm.assume(caller != address(this));
        // Basic sanity: newOwner should not be the zero address (transferOwnership requires it).
        vm.assume(newOwner != address(0));
        // Ensure the caller is not the current owner already (implicitly true from first assume, but explicit nonetheless).
        vm.assume(caller != originalOwner);

        // Attempt the transferOwnership as the fuzzed caller.
        bool success;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // After any call, the owner must NOT change when the caller is not the current owner.
        // The reference contract ensures this (call reverts -> success false, owner unchanged).
        // The buggy version allows the transfer (success true, owner changed).
        // So the invariant: if caller is NOT the owner, the owner must remain originalOwner.
        assertTrue(c.owner() == originalOwner);
    }
}

