// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_OPERATOR = address(0x1234);

    function setUp() public {
        // Use a non-zero initial operator so that a change can be detected
        c = new C(INITIAL_OPERATOR, IERC20(address(0)), ICVXBooster(address(0)), new address[](0));
    }

    function testFuzz_property(address caller, address newOperator) public {
        // caller must not be the owner (who is this test contract)
        vm.assume(caller != address(this));
        // newOperator must differ from the initial operator to detect a change
        vm.assume(newOperator != INITIAL_OPERATOR);

        // Attempt to change the operator from a non-owner address
        vm.prank(caller);
        c.setOperator(newOperator);

        // PROPERTY: After a non-owner calls setOperator, the operator MUST remain the initial value.
        // Reference: onlyOwner prevents the change, so operator stays INITIAL_OPERATOR.
        // Buggy: modifier does nothing, allowing the change, so operator becomes newOperator.
        assertEq(c.operator(), INITIAL_OPERATOR);
    }
}

