import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address caller, address other) public {
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);
        vm.assume(caller != address(this) && other != address(this));

        address deployer = address(this);

        // Call owner() from the deployer (this contract) to get the reference owner
        address ownerFromDeployer = c.owner();

        // Call owner() from a different EOA (caller)
        vm.prank(caller);
        address ownerFromCaller = c.owner();

        // Call owner() from another different EOA (other)
        vm.prank(other);
        address ownerFromOther = c.owner();

        // The invariant: owner() must be independent of the caller and equal to the deployer's view
        assertTrue(ownerFromDeployer == ownerFromCaller && ownerFromDeployer == ownerFromOther);
    }
}

